  UNIQUE KEY `student_id_2` (`student_id`,`assessment_id`,`education_subject_id`,`education_grade_id`,`academic_period_id`,`assessment_period_id`,`institution_classes_id`),
  KEY `assessment_grading_option_id` (`assessment_grading_option_id`),
