  `infrastructure_wash_water_type_id` int NOT NULL COMMENT 'links to infrastructure_wash_water_types.id',
  `infrastructure_wash_water_functionality_id` int NOT NULL COMMENT 'links to infrastructure_wash_water_functionalities.id',
