  `infrastructure_wash_water_accessibility_id` int NOT NULL COMMENT 'links to infrastructure_wash_water_accessibilities.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `academic_period_id` (`academic_period_id`),
  KEY `institution_id` (`institution_id`),
  KEY `infrastructure_wash_water_type_id` (`infrastructure_wash_water_type_id`),
  KEY `infrastructure_wash_water_functionality_id` (`infrastructure_wash_water_functionality_id`),
  KEY `infrastructure_wash_water_proximity_id` (`infrastructure_wash_water_proximity_id`),
  KEY `infrastructure_wash_water_quantity_id` (`infrastructure_wash_water_quantity_id`),
  KEY `infrastructure_wash_water_quality_id` (`infrastructure_wash_water_quality_id`),
  KEY `infrastructure_wash_water_accessibility_id` (`infrastructure_wash_water_accessibility_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains infrastructure waters';

