--
-- Table structure for table `institutions`
--

CREATE TABLE IF NOT EXISTS `institutions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `alternative_name` varchar(150) DEFAULT NULL,
  `code` varchar(20) NOT NULL,
  `address` text NOT NULL,
  `postal_code` varchar(20) DEFAULT NULL,
  `contact_person` varchar(100) DEFAULT NULL,
  `telephone` varchar(30) DEFAULT NULL,
  `fax` varchar(30) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `website` varchar(100) DEFAULT NULL,
  `date_opened` date NOT NULL,
  `year_opened` int NOT NULL,
  `date_closed` date DEFAULT NULL,
  `year_closed` int DEFAULT NULL,
  `longitude` varchar(25) DEFAULT NULL,
  `latitude` varchar(25) DEFAULT NULL,
  `logo_name` varchar(250) DEFAULT NULL,
  `logo_content` longblob,
  `shift_type` int NOT NULL COMMENT '1=Single Shift Owner, 2=Single Shift Occupier, 3=Multiple Shift Owner, 4=Multiple Shift Occupier',
  `classification` int NOT NULL DEFAULT '1' COMMENT '1 -> Academic Institution, 2 -> Non-academic institution',
  `area_id` int NOT NULL COMMENT 'links to areas.id',
  `area_administrative_id` int NOT NULL,
  `institution_locality_id` int NOT NULL COMMENT 'links to institution_localities.id',
  `institution_type_id` int NOT NULL COMMENT 'links to institution_types.id',
  `institution_ownership_id` int NOT NULL COMMENT 'links to institution_ownerships.id',
  `institution_status_id` int NOT NULL COMMENT 'links to institution_statuses.id',
  `institution_sector_id` int NOT NULL COMMENT 'links to institution_sectors.id',
  `institution_provider_id` int NOT NULL COMMENT 'links to institution_providers.id',
  `institution_gender_id` int NOT NULL COMMENT 'links to institution_genders.id',
  `security_group_id` int NOT NULL DEFAULT '0',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `area_id` (`area_id`),
  KEY `security_group_id` (`security_group_id`),
  KEY `institution_locality_id` (`institution_locality_id`),
  KEY `institution_type_id` (`institution_type_id`),
  KEY `institution_ownership_id` (`institution_ownership_id`),
  KEY `institution_status_id` (`institution_status_id`),
  KEY `institution_sector_id` (`institution_sector_id`),
  KEY `institution_provider_id` (`institution_provider_id`),
  KEY `institution_gender_id` (`institution_gender_id`),
  KEY `area_administrative_id` (`area_administrative_id`),
  KEY `name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains information of every institution';

-- --------------------------------------------------------

--
-- Table structure for table `institution_activities`
--

CREATE TABLE IF NOT EXISTS `institution_activities` (
  `id` int NOT NULL AUTO_INCREMENT,
  `model` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `model_reference` int NOT NULL,
  `field` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `old_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `new_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operation` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `institution_id` int NOT NULL COMMENT 'links to institutions.id',
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `model_reference` (`model_reference`),
  KEY `institution_id` (`institution_id`),
  KEY `created_user_id` (`created_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains all modification of information related to every institution';

-- --------------------------------------------------------

--
-- Table structure for table `institution_assets`
--

CREATE TABLE IF NOT EXISTS `institution_assets` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `asset_make_id` int DEFAULT NULL,
  `asset_model_id` int DEFAULT NULL,
  `serial_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `purchase_order` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cost` decimal(50,2) DEFAULT NULL,
  `stocktake_date` date DEFAULT NULL,
  `lifespan` int DEFAULT NULL,
  `institution_room_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `depreciation` decimal(50,2) DEFAULT NULL,
  `purchase_date` date DEFAULT NULL,
  `accessibility` int NOT NULL COMMENT '0 -> Not Accessible, 1 -> Accessible',
  `purpose` int NOT NULL COMMENT '0 -> Non-Teaching, 1 -> Teaching',
  `institution_id` int NOT NULL COMMENT 'links to institutions.id',
  `asset_status_id` int NOT NULL COMMENT 'links to asset_statuses.id',
  `asset_type_id` int NOT NULL COMMENT 'links to asset_types.id',
  `asset_condition_id` int NOT NULL COMMENT 'links to asset_conditions.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `institution_id` (`institution_id`),
  KEY `asset_status_id` (`asset_status_id`),
  KEY `asset_type_id` (`asset_type_id`),
  KEY `asset_condition_id` (`asset_condition_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`),
  KEY `asset_make_id` (`asset_make_id`),
  KEY `asset_model_id` (`asset_model_id`),
  KEY `serial_number` (`serial_number`),
  KEY `purchase_order` (`purchase_order`),
  KEY `stocktake_date` (`stocktake_date`),
  KEY `institution_room_id` (`institution_room_id`),
  KEY `user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains all assets used by institutions';

