  `infrastructure_condition_id` int NOT NULL COMMENT 'links to infrastructure_conditions.id',
  `previous_institution_land_id` int DEFAULT NULL COMMENT 'links to institution_lands.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `code` (`code`),
  KEY `accessibility` (`accessibility`),
  KEY `institution_id` (`institution_id`),
  KEY `academic_period_id` (`academic_period_id`),
  KEY `land_type_id` (`land_type_id`),
  KEY `land_status_id` (`land_status_id`),
  KEY `infrastructure_ownership_id` (`infrastructure_ownership_id`),
  KEY `infrastructure_condition_id` (`infrastructure_condition_id`),
  KEY `previous_institution_land_id` (`previous_institution_land_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains all land information of all institutions';

