  `id` int NOT NULL AUTO_INCREMENT,
  `action` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'function name for moodle',
  `params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'stores params data in json',
  `response` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'stores response data in json',
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  `status` int NOT NULL COMMENT '1 = success, 2 = failed',
  `callback` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'function name from MoodleApi.php that was executed',
  `callback_param` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'stores serialized param data',
  PRIMARY KEY (`id`),
  KEY `action` (`action`),
  KEY `created_user_id` (`created_user_id`),
  KEY `status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table serves as a log. It also stores failed attempts.';

