-- Table structure for table `rubric_criterias`
--

CREATE TABLE IF NOT EXISTS `rubric_criterias` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(250) NOT NULL,
  `order` int NOT NULL DEFAULT '0',
  `type` int NOT NULL DEFAULT '1' COMMENT '1 -> Section Break, 2 -> Dropdown',
  `rubric_section_id` int NOT NULL COMMENT 'links to rubric_sections.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `rubric_section_id` (`rubric_section_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains the criterias used in a rubric template section';

-- --------------------------------------------------------

--
-- Table structure for table `rubric_criteria_options`
--

CREATE TABLE IF NOT EXISTS `rubric_criteria_options` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(250) NOT NULL,
  `rubric_template_option_id` int NOT NULL COMMENT 'links to rubric_template_options.id',
  `rubric_criteria_id` int NOT NULL COMMENT 'links to rubric_criterias.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `rubric_template_option_id` (`rubric_template_option_id`),
  KEY `rubric_criteria_id` (`rubric_criteria_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains the options of a rubric criteria';

-- --------------------------------------------------------

--
-- Table structure for table `rubric_sections`
--

CREATE TABLE IF NOT EXISTS `rubric_sections` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(250) NOT NULL,
  `order` int NOT NULL DEFAULT '0',
  `rubric_template_id` int NOT NULL COMMENT 'links to rubric_templates.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `rubric_template_id` (`rubric_template_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains the sections used in a rubric template';

-- --------------------------------------------------------

--
-- Table structure for table `rubric_statuses`
--

CREATE TABLE IF NOT EXISTS `rubric_statuses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `date_enabled` date NOT NULL,
  `date_disabled` date NOT NULL,
  `status` int NOT NULL DEFAULT '1',
  `rubric_template_id` int NOT NULL COMMENT 'links to rubric_templates.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `rubric_template_id` (`rubric_template_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table indicates the date period that allows user for data entry';

-- --------------------------------------------------------

--
-- Table structure for table `rubric_status_periods`
--

CREATE TABLE IF NOT EXISTS `rubric_status_periods` (
  `id` char(36) NOT NULL,
  `academic_period_id` int NOT NULL COMMENT 'links to academic_periods.id',
  `rubric_status_id` int NOT NULL COMMENT 'links to rubric_statuses.id',
  PRIMARY KEY (`id`),
  KEY `academic_period_id` (`academic_period_id`),
  KEY `rubric_status_id` (`rubric_status_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table indicates the rubrics is done for which academic period';

-- --------------------------------------------------------

--
-- Table structure for table `rubric_status_programmes`
