  `education_programme_id` int NOT NULL COMMENT 'links to education_programmes.id',
  `rubric_status_id` int NOT NULL COMMENT 'links to rubric_statuses.id',
  PRIMARY KEY (`id`),
  KEY `education_programme_id` (`education_programme_id`),
  KEY `rubric_status_id` (`rubric_status_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table indicates the education programme offered by the school that can access the rubrics';

-- --------------------------------------------------------

--
-- Table structure for table `rubric_status_roles`
--

CREATE TABLE IF NOT EXISTS `rubric_status_roles` (
  `id` char(36) NOT NULL,
  `rubric_status_id` int NOT NULL COMMENT 'links to rubric_statuses.id',
  `security_role_id` int NOT NULL COMMENT 'links to security_roles.id',
  PRIMARY KEY (`id`),
  KEY `rubric_status_id` (`rubric_status_id`),
  KEY `security_role_id` (`security_role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table indicates the roles that can access the rubrics';

