--
-- Table structure for table `scholarships`
--

CREATE TABLE IF NOT EXISTS `scholarships` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `application_open_date` date NOT NULL,
  `application_close_date` date NOT NULL,
  `maximum_award_amount` decimal(15,2) NOT NULL,
  `total_amount` decimal(15,2) NOT NULL,
  `duration` int NOT NULL,
  `bonded_organisation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bond` int DEFAULT NULL,
  `requirements` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `instructions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `scholarship_financial_assistance_type_id` int NOT NULL COMMENT 'links to scholarship_financial_assistance_types.id',
  `scholarship_financial_assistance_id` int DEFAULT NULL,
  `scholarship_funding_source_id` int DEFAULT NULL COMMENT 'links to scholarship_funding_sources.id',
  `academic_period_id` int NOT NULL COMMENT 'links to academic_periods.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `scholarship_financial_assistance_type_id` (`scholarship_financial_assistance_type_id`),
  KEY `scholarship_funding_source_id` (`scholarship_funding_source_id`),
  KEY `academic_period_id` (`academic_period_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`),
  KEY `scholarship_financial_assistance_id` (`scholarship_financial_assistance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of scholarships';

-- --------------------------------------------------------

--
-- Table structure for table `scholarships_field_of_studies`
--

CREATE TABLE IF NOT EXISTS `scholarships_field_of_studies` (
  `scholarship_id` int NOT NULL COMMENT 'links to scholarships.id',
  `education_field_of_study_id` int NOT NULL COMMENT 'links to education_field_of_studies.id',
  PRIMARY KEY (`scholarship_id`,`education_field_of_study_id`),
  KEY `scholarship_id` (`scholarship_id`),
  KEY `education_field_of_study_id` (`education_field_of_study_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of field of studies linked to specific scholarship';

-- --------------------------------------------------------

--
-- Table structure for table `scholarships_scholarship_attachment_types`
--

CREATE TABLE IF NOT EXISTS `scholarships_scholarship_attachment_types` (
  `scholarship_id` int NOT NULL COMMENT 'links to scholarships.id',
  `scholarship_attachment_type_id` int NOT NULL COMMENT 'links to scholarship_attachment_types.id',
  `is_mandatory` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`scholarship_id`,`scholarship_attachment_type_id`),
  KEY `scholarship_id` (`scholarship_id`),
  KEY `scholarship_attachment_type_id` (`scholarship_attachment_type_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of attachment types linked to specific scholarship';

