--
-- Table structure for table `scholarship_applications`
--

CREATE TABLE IF NOT EXISTS `scholarship_applications` (
  `id` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `applicant_id` int NOT NULL COMMENT 'links to security_users.id',
  `scholarship_id` int NOT NULL COMMENT 'links to scholarships.id',
  `requested_amount` decimal(15,2) DEFAULT NULL,
  `comments` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status_id` int NOT NULL COMMENT 'links to workflow_steps.id',
  `assignee_id` int NOT NULL DEFAULT '0' COMMENT 'links to security_users.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`applicant_id`,`scholarship_id`),
  KEY `applicant_id` (`applicant_id`),
  KEY `scholarship_id` (`scholarship_id`),
  KEY `status_id` (`status_id`),
  KEY `assignee_id` (`assignee_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of applications linked to specific scholarship';

