  `file_content` longblob NOT NULL,
  `scholarship_attachment_type_id` int NOT NULL COMMENT 'links to scholarship_attachment_types.id',
  `applicant_id` int NOT NULL COMMENT 'links to security_users.id',
  `scholarship_id` int NOT NULL COMMENT 'links to scholarships.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `scholarship_attachment_type_id` (`scholarship_attachment_type_id`),
  KEY `applicant_id` (`applicant_id`),
  KEY `scholarship_id` (`scholarship_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of attachments linked to specific scholarship application';

-- --------------------------------------------------------

--
-- Table structure for table `scholarship_application_institution_choices`
--

CREATE TABLE IF NOT EXISTS `scholarship_application_institution_choices` (
  `id` int NOT NULL AUTO_INCREMENT,
  `location_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DOMESTIC, INTERNATIONAL',
  `scholarship_institution_choice_type_id` int NOT NULL COMMENT 'links to scholarship_institution_choice_types.id',
  `estimated_cost` decimal(15,2) NOT NULL,
  `course_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `is_selected` int NOT NULL DEFAULT '0' COMMENT '0 -> No, 1 -> Yes',
  `order` int NOT NULL,
  `country_id` int NOT NULL DEFAULT '0' COMMENT 'links to countries.id',
  `scholarship_institution_choice_status_id` int NOT NULL COMMENT 'links to scholarship_institution_choice_statuses.id',
  `education_field_of_study_id` int NOT NULL COMMENT 'links to education_field_of_studies.id',
  `qualification_level_id` int NOT NULL COMMENT 'links to qualification_levels.id',
  `applicant_id` int NOT NULL COMMENT 'links to security_users.id',
  `scholarship_id` int NOT NULL COMMENT 'links to scholarships.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `country_id` (`country_id`),
  KEY `scholarship_institution_choice_status_id` (`scholarship_institution_choice_status_id`),
  KEY `education_field_of_study_id` (`education_field_of_study_id`),
  KEY `qualification_level_id` (`qualification_level_id`),
  KEY `applicant_id` (`applicant_id`),
  KEY `scholarship_id` (`scholarship_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`),
  KEY `scholarship_institution_choice_type_id` (`scholarship_institution_choice_type_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of institution choices linked to specific scholarship application';

