  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This is a field option table containing the list of user-defined types of leave used by institution_staff_leave';

