--
-- Table structure for table `staff_licenses`
--

CREATE TABLE IF NOT EXISTS `staff_licenses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `license_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issue_date` date NOT NULL,
  `expiry_date` date DEFAULT NULL,
  `issuer` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
