CREATE TABLE IF NOT EXISTS `summary_area_institution_grade_attendances` (
  `academic_period_id` int DEFAULT NULL,
  `academic_period_name` varchar(150) DEFAULT NULL,
  `area_id` int DEFAULT NULL,
  `area_code` varchar(150) DEFAULT NULL,
  `area_name` varchar(150) DEFAULT NULL,
  `institution_id` int DEFAULT NULL,
  `institution_code` varchar(150) DEFAULT NULL,
  `institution_name` varchar(150) DEFAULT NULL,
  `education_grade_id` int DEFAULT NULL,
  `education_grade_code` varchar(150) DEFAULT NULL,
  `education_grade_name` varchar(150) DEFAULT NULL,
  `attendance_date` date DEFAULT NULL,
  `marked_classes` int DEFAULT NULL,
  `total_classes` int DEFAULT NULL,
  `female_count` int DEFAULT NULL,
  `male_count` int DEFAULT NULL,
  `total_count` int DEFAULT NULL,
  `present_female_count` int DEFAULT NULL,
  `present_male_count` int DEFAULT NULL,
  `present_total_count` int DEFAULT NULL,
  `absent_female_count` int DEFAULT NULL,
  `absent_male_count` int DEFAULT NULL,
  `absent_total_count` int DEFAULT NULL,
  `late_female_count` int DEFAULT NULL,
  `late_male_count` int DEFAULT NULL,
  `late_total_count` int DEFAULT NULL,
  `created` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=COMPACT;

--
-- Triggers `summary_area_institution_grade_attendances`
--
DELIMITER $$
CREATE TRIGGER `trigger_summary_area_institution_grade_attendances_update` BEFORE UPDATE ON `summary_area_institution_grade_attendances` FOR EACH ROW BEGIN SET NEW.present_total_count = NEW.present_female_count + NEW.present_male_count, NEW.absent_total_count = NEW.absent_female_count + NEW.absent_male_count, NEW.late_total_count = NEW.late_female_count + NEW.late_male_count; END
$$
DELIMITER ;

