  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `survey_question_id` (`survey_question_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains the choices for dropdown-type questions';

