  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `survey_form_id` (`survey_form_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table indicates the date period that allows user for data entry' TABLESPACE `innodb_system`;

