--
-- Table structure for table `webhooks`
--

CREATE TABLE IF NOT EXISTS `webhooks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` int NOT NULL COMMENT '0 -> Inactive, 1 -> Active',
  `url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `method` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'POST -> HTTP Post Method, GET -> HTTP Get Method, PUT -> HTTP Put Method, DELETE -> HTTP Delete Method, PATCH -> HTTP Patch Method',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of webhooks';

-- --------------------------------------------------------

--
-- Table structure for table `webhook_events`
--

CREATE TABLE IF NOT EXISTS `webhook_events` (
  `webhook_id` int NOT NULL,
  `event_key` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`webhook_id`,`event_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of webhook events';

-- --------------------------------------------------------

--
-- Table structure for table `workflows`
--

CREATE TABLE IF NOT EXISTS `workflows` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(60) NOT NULL,
  `name` varchar(100) NOT NULL,
  `message` text,
  `workflow_model_id` int NOT NULL COMMENT 'links to workflow_models.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `workflow_model_id` (`workflow_model_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains all user defined workflows used by the system';

-- --------------------------------------------------------

--
-- Table structure for table `workflows_filters`
--

CREATE TABLE IF NOT EXISTS `workflows_filters` (
  `id` char(36) NOT NULL,
  `workflow_id` int NOT NULL COMMENT 'links to workflows.id',
  `filter_id` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `filter_id` (`filter_id`),
  KEY `workflow_id` (`workflow_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table indicates the workflows triggered by the staff leave type';

-- --------------------------------------------------------

--
-- Table structure for table `workflow_actions`
--

CREATE TABLE IF NOT EXISTS `workflow_actions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `action` int DEFAULT NULL COMMENT '0 -> Approve, 1 -> Reject',
  `visible` int NOT NULL DEFAULT '1',
  `comment_required` int NOT NULL DEFAULT '0',
  `allow_by_assignee` int NOT NULL DEFAULT '0',
  `event_key` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `workflow_step_id` int NOT NULL COMMENT 'links to workflow_steps.id',
  `next_workflow_step_id` int NOT NULL,
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `allow_by_assignee` (`allow_by_assignee`),
  KEY `next_workflow_step_id` (`next_workflow_step_id`),
  KEY `workflow_step_id` (`workflow_step_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains all actions used by different steps of any workflow';

-- --------------------------------------------------------

--
-- Table structure for table `workflow_comments`
--

CREATE TABLE IF NOT EXISTS `workflow_comments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `comment` text NOT NULL,
  `workflow_record_id` int NOT NULL COMMENT 'links to workflow_records.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `workflow_record_id` (`workflow_record_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains comments added by users when performing a workflow action';

-- --------------------------------------------------------

--
-- Table structure for table `workflow_models`
--

CREATE TABLE IF NOT EXISTS `workflow_models` (
  `id` int NOT NULL,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `model` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `filter` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_school_based` int NOT NULL DEFAULT '0',
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `created_user_id` (`created_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of features that are workflow-enabled';

-- --------------------------------------------------------

--
-- Table structure for table `workflow_rules`
--

CREATE TABLE IF NOT EXISTS `workflow_rules` (
  `id` int NOT NULL AUTO_INCREMENT,
  `rule` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `feature` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `workflow_id` int NOT NULL COMMENT 'links to workflows.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `workflow_id` (`workflow_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains workflow rules associates with a specific workflow';

-- --------------------------------------------------------

--
-- Table structure for table `workflow_rule_events`
--

CREATE TABLE IF NOT EXISTS `workflow_rule_events` (
  `workflow_rule_id` int NOT NULL COMMENT 'links to workflow_rules.id',
  `event_key` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`workflow_rule_id`,`event_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of workflow rule events';

