CREATE TABLE IF NOT EXISTS `workflow_statuses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL,
  `name` varchar(150) NOT NULL,
  `is_editable` int NOT NULL,
  `is_removable` int NOT NULL,
  `workflow_model_id` int NOT NULL COMMENT 'links to workflow_models.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `workflow_model_id` (`workflow_model_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains the list of system-defined and user-defined statuses that are used by reports and other features';

