  `workflow_step_id` int NOT NULL COMMENT 'links to workflow_steps.id',
  PRIMARY KEY (`id`),
  KEY `workflow_status_id` (`workflow_status_id`),
  KEY `workflow_step_id` (`workflow_step_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains the list of steps belonging to which status';

-- --------------------------------------------------------

--
-- Table structure for table `workflow_steps`
--

CREATE TABLE IF NOT EXISTS `workflow_steps` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` int NOT NULL DEFAULT '0' COMMENT '1 -> TO DO, 2 -> IN PROGRESS, 3 -> DONE',
  `is_editable` int NOT NULL DEFAULT '0',
  `is_removable` int NOT NULL DEFAULT '0',
  `is_system_defined` int NOT NULL DEFAULT '0',
  `workflow_id` int NOT NULL COMMENT 'links to workflows.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `category` (`category`),
  KEY `workflow_id` (`workflow_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of steps used by all workflows';

-- --------------------------------------------------------

--
-- Table structure for table `workflow_steps_params`
--

CREATE TABLE IF NOT EXISTS `workflow_steps_params` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `workflow_step_id` int NOT NULL COMMENT 'links to workflow_steps.id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `workflow_step_id` (`workflow_step_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of params belonging to which step';

