  PRIMARY KEY (`id`),
  KEY `security_role_id` (`security_role_id`),
  KEY `workflow_step_id` (`workflow_step_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains the list of steps accessible by which roles';

-- --------------------------------------------------------

--
-- Table structure for table `workflow_transitions`
--

CREATE TABLE IF NOT EXISTS `workflow_transitions` (
  `id` int NOT NULL AUTO_INCREMENT,
