  `status` int NOT NULL DEFAULT '1' COMMENT '0 -> Inactive, 1 -> Active',
  `last_login` datetime DEFAULT NULL,
  `failed_logins` int NOT NULL DEFAULT '0',
  `photo_name` varchar(250) DEFAULT '',
  `photo_content` longblob,
  `preferred_language` char(2) DEFAULT NULL,
  `is_student` int NOT NULL DEFAULT '0',
  `is_staff` int NOT NULL DEFAULT '0',
  `is_guardian` int NOT NULL DEFAULT '0',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `openemis_no_UNIQUE` (`openemis_no`),
  UNIQUE KEY `username_UNIQUE` (`username`),
  UNIQUE KEY `openemis_no_UNIQUE_openemis_no` (`openemis_no`),
  UNIQUE KEY `username_UNIQUE_username` (`username`),
  KEY `first_name` (`first_name`),
  KEY `last_name` (`last_name`),
  KEY `gender_id` (`gender_id`),
  KEY `address_area_id` (`address_area_id`),
  KEY `birthplace_area_id` (`birthplace_area_id`),
  KEY `status` (`status`),
  KEY `middle_name` (`middle_name`),
  KEY `third_name` (`third_name`),
  KEY `is_student` (`is_student`),
  KEY `is_staff` (`is_staff`),
  KEY `is_guardian` (`is_guardian`),
  KEY `super_admin` (`super_admin`),
  KEY `identity_number` (`identity_number`),
  KEY `is_student_2` (`is_student`,`first_name`,`last_name`,`gender_id`,`date_of_birth`),
  KEY `secur_users_fk_ide_typ_id` (`identity_type_id`),
  KEY `secur_users_fk_natio_id` (`nationality_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains all user information';

